import {listTierlists,manageTierlist,likeTierlist} from './tierlist-api.mjs?v=20261015-1';
import {cleanList} from './tierlist-model.mjs?v=appearance-assets';import {drawTierlist} from './tierlist-render.mjs?v=appearance-assets';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};let mine=new URL(location.href).searchParams.get('view')==='mine',records=[],units=[],generation=0;
const status=s=>$('library-status').textContent=s;
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);e.target.render?.()}},{rootMargin:'100px'});
const dialog=el('dialog',undefined,'formation-image-dialog');dialog.setAttribute('aria-label','Tierlist image');document.body.append(dialog);
async function inspect(record){const heading=el('h2',record.name),canvas=el('canvas'),actions=el('div',undefined,'modal-actions'),open=el('a',mine?'Edit draft':'Open as draft','btn');open.href=new URL('./drafter/tierlist.html',import.meta.url).href+'?tierlist='+encodeURIComponent(record.id)+(mine?'&private=1':'');const close=el('button','Close','btn secondary');close.type='button';close.onclick=()=>dialog.close();actions.append(open,close);dialog.replaceChildren(heading,canvas,actions);dialog.showModal();try{await drawTierlist(canvas,cleanList(record.payload,units),units)}catch(e){dialog.close();status(e.message)}}
async function load(){const token=++generation;$('mine-view').setAttribute('aria-pressed',String(mine));$('public-view').setAttribute('aria-pressed',String(!mine));status('Loading tierlists…');try{const loaded=await listTierlists(mine);if(token!==generation)return;records=loaded;render();status(records.length+' tierlists.')}catch(e){if(token!==generation)return;records=[];render();status(e.message)}}
function render(){observer.disconnect();const list=$('tierlist-library'),q=$('library-search').value.toLowerCase(),shown=records.filter(r=>(!$('library-mode').value||(r.payload.view||'list')===$('library-mode').value)&&(!q||(r.name+' '+(r.payload.shareAuthor||'')).toLowerCase().includes(q)));if($('library-sort').value==='likes')shown.sort((a,b)=>(b.likes||0)-(a.likes||0));list.replaceChildren();if(!shown.length){list.append(el('div',mine?'Your saved tierlists will appear here.':'Published community tierlists will appear here.','library-empty')); return}for(const r of shown){const card=el('article',undefined,'formation-entry tierlist-entry'),canvas=el('canvas');canvas.setAttribute('aria-label',r.name+' ranking preview');canvas.render=()=>drawTierlist(canvas,cleanList(r.payload,units),units).catch(e=>status(e.message));observer.observe(canvas);const preview=el('button',undefined,'formation-image-button');preview.type='button';preview.setAttribute('aria-label','View '+r.name);preview.onclick=()=>inspect(r);preview.append(canvas);card.append(preview,el('h2',r.name),el('p',(r.payload.view==='chart'?'Alignment chart':'Tierlist')+' · '+(r.payload.tier===0?'All tiers':'Tier '+r.payload.tier)+(r.payload.shareAuthor?' · '+r.payload.shareAuthor:''),'caption'));if(r.payload.notes)card.append(el('p',r.payload.notes,'formation-card-note'));const actions=el('div',undefined,'row'),open=el('a',mine?'Edit draft':'Open','btn secondary');open.href=new URL('./drafter/tierlist.html',import.meta.url).href+'?tierlist='+encodeURIComponent(r.id)+(mine?'&private=1':'');actions.append(open);if(!mine){const like=el('button','Like '+(r.likes||0),'btn secondary');like.setAttribute('aria-pressed',String(!!r.liked));like.onclick=async()=>{like.disabled=true;try{const result=await likeTierlist(r.id);r.likes=result.likes;r.liked=result.liked;like.textContent='Like '+result.likes;like.setAttribute('aria-pressed',String(result.liked))}catch(e){status(e.message)}finally{like.disabled=false}};actions.prepend(like)}else{card.append(el('p',r.published?'Private draft + published snapshot':'Private draft'));for(const action of [...(r.published?['unpublish']:[]),'delete']){const b=el('button',action==='delete'?'Delete':'Unpublish','btn secondary');b.onclick=async()=>{if(!confirm(action==='delete'?'Delete this tierlist and its public version?':'Unpublish this tierlist? Your private draft remains.'))return;b.disabled=true;try{await manageTierlist(r.id,r.revision,action);await load()}catch(e){status(e.message);b.disabled=false}};actions.append(b)}}card.append(actions);list.append(card)}}
$('public-view').onclick=()=>{mine=false;load()};$('mine-view').onclick=()=>{mine=true;load()};$('refresh').onclick=load;$('library-search').oninput=render;$('library-mode').onchange=render;$('library-sort').onchange=render;
try{const r=await fetch(new URL('./tatari-data/roster.json',import.meta.url));if(!r.ok)throw Error('Tatari data unavailable.');units=(await r.json()).units;await load()}catch(e){status(e.message)}
